import { text } from "@ai-werewolf-arena/game-text";
import { runCli, takeDisplayArguments, type CliDisplayContext } from "./display";
import { loadRuntimeConfig } from "../config/load_config";
import { loadBoardDefinition } from "../config/load_board_definition";
import { resolveGameSetup, resolveGameBoard } from "../config/resolve_game_setup";
import { describeResolvedSetup } from "../config/describe_setup";
import { resolveCliConfigDirectory } from "./config_directory";

export async function checkConfig(
  configDir: string,
  gameName: string,
  display?: CliDisplayContext,
) {
  const runtime = await loadRuntimeConfig({ configDir, gameName });
  const board = await loadBoardDefinition(configDir, resolveGameBoard(runtime));
  const setup = resolveGameSetup(runtime, {}, board);
  if (display && !display.explicit) display.locale = setup.context.displayLocale;
  return describeResolvedSetup(setup, display?.locale);
}

export { configDiagnostic } from "../config/error_codes";

export async function main(
  argv = process.argv.slice(2),
  display: CliDisplayContext = { locale: "zh-CN", explicit: false },
): Promise<void> {
  const args = takeDisplayArguments(argv, display);
  const values: Record<string, string> = {};
  for (let i = 0; i < args.length; i += 2) {
    if (
      !["--configs-dir", "--game-config-name"].includes(args[i]) ||
      !args[i + 1] ||
      args[i + 1].startsWith("--")
    )
      throw new Error("config_check_usage");
    values[args[i]] = args[i + 1];
  }
  const result = await checkConfig(
    resolveCliConfigDirectory(values["--configs-dir"]),
    values["--game-config-name"] ?? "default",
    display,
  );
  console.log(
    JSON.stringify({ ...result, message: text(display.locale, "cli.config_checked") }, null, 2),
  );
}

if (require.main === module) void runCli(main);

import path from "node:path";

/** Defaults are project-relative; explicit and environment paths remain cwd-relative. */
export function resolveCliConfigDirectory(
  explicit?: string,
  environment: NodeJS.ProcessEnv = process.env,
): string {
  return (
    explicit ?? environment.GAME_CONFIGS_DIR ?? path.resolve(__dirname, "../../../..", "configs")
  );
}

import { resolveCliConfigDirectory } from "./config_directory";
import { text, type Locale } from "@ai-werewolf-arena/game-text";
import { runCli, takeDisplayArguments, type CliDisplayContext } from "./display";
import {
  readFile,
  writeFile,
  readdir,
  access,
  mkdir,
  unlink,
  rename,
  link,
  stat,
  open,
  type FileHandle,
} from "node:fs/promises";
import { randomUUID } from "node:crypto";
import path from "node:path";
import { convertLegacyBoard, type MigrationWarningCode } from "../config/migrate_board";
import { CONFIG_ID_PATTERN } from "../config/board_definition";
import type { BoardName } from "../scenarios/board_config_resolver";

async function ensureBackup(file: string, original: string): Promise<void> {
  const backup = `${file}.v1.bak`;
  try {
    await writeFile(backup, original, { flag: "wx", mode: 0o600 });
  } catch (error) {
    if ((error as NodeJS.ErrnoException).code !== "EEXIST") throw error;
    if ((await readFile(backup, "utf8")) !== original)
      throw new Error("board_config_migration_backup_conflict");
  }
}

/** Publish a complete JSON file; an exclusive target is never removed on collision. */
async function publishBoard(file: string, content: string, exclusive = false): Promise<void> {
  const temporary = `${file}.${randomUUID()}.tmp`;
  const mode = exclusive ? 0o600 : (await stat(file)).mode & 0o777;
  let owned = false;
  let failure: unknown;
  let handle: FileHandle | undefined;
  try {
    handle = await open(temporary, "wx", mode);
    owned = true;
    await handle.writeFile(content);
    await handle.close();
    handle = undefined;
    if (exclusive) await link(temporary, file);
    else await rename(temporary, file);
  } catch (error) {
    failure = error;
  }
  if (handle) {
    try {
      await handle.close();
    } catch (error) {
      failure = new AggregateError([failure, error], "board_config_migration_cleanup_failed");
    }
  }
  if (owned) {
    try {
      await unlink(temporary);
    } catch (error) {
      if ((error as NodeJS.ErrnoException).code !== "ENOENT") {
        if (failure)
          throw new AggregateError([failure, error], "board_config_migration_cleanup_failed");
        throw error;
      }
    }
  }
  if (failure) throw failure;
}

export async function migrateBoardSource(
  configDir: string,
  boardId: string,
  source: string,
  legacyBase: BoardName | undefined,
  apply: boolean,
  displayLocale: Locale = "zh-CN",
): Promise<void> {
  if (!CONFIG_ID_PATTERN.test(boardId)) throw new Error("board_config_id_invalid");
  const sourceFile = path.resolve(source);
  const target = path.resolve(configDir, "boards", `${boardId}.json`);
  let existed = true;
  try {
    await access(target);
  } catch (error) {
    if ((error as NodeJS.ErrnoException).code === "ENOENT") existed = false;
    else throw error;
  }
  if (existed && target !== sourceFile) throw new Error("board_config_migration_target_exists");
  const original = await readFile(sourceFile, "utf8");
  let raw: unknown;
  try {
    raw = JSON.parse(original);
  } catch {
    throw new Error("board_config_json_invalid");
  }
  const result = convertLegacyBoard(raw, boardId, legacyBase);
  const report = JSON.stringify(
    {
      mode: apply ? "apply" : "preview",
      boardId,
      sourceFile,
      target,
      warnings: result.warnings,
      message: text(displayLocale, "cli.migrated"),
      warningMessages: migrationWarningMessages(result.warnings, displayLocale),
    },
    null,
    2,
  );
  if (apply) {
    await ensureBackup(sourceFile, original);
    await mkdir(path.dirname(target), { recursive: true });
    try {
      await publishBoard(target, JSON.stringify(result.definition, null, 2) + "\n", !existed);
    } catch (error) {
      if (existed) {
        try {
          await publishBoard(target, original);
        } catch (rollback) {
          throw new AggregateError([error, rollback], "board_config_migration_rollback_failed");
        }
      }
      throw error;
    }
  }
  console.log(report);
}

export async function migrateBoards(
  configDir: string,
  apply: boolean,
  displayLocale: Locale = "zh-CN",
): Promise<void> {
  const root = path.resolve(configDir, "boards");
  const changes: Array<{
    file: string;
    original: string;
    converted: string;
    id: string;
    warnings: MigrationWarningCode[];
  }> = [];
  for (const filename of (await readdir(root)).filter((name) => name.endsWith(".json")).sort()) {
    const id = filename.slice(0, -5);
    const file = path.join(root, filename);
    const original = await readFile(file, "utf8");
    let raw: unknown;
    try {
      raw = JSON.parse(original);
    } catch {
      throw new Error(`board_config_json_invalid: ${id}`);
    }
    const converted = convertLegacyBoard(raw, id);
    if (raw && typeof raw === "object" && "version" in raw) continue;
    changes.push({
      file,
      original,
      converted: JSON.stringify(converted.definition, null, 2) + "\n",
      id,
      warnings: converted.warnings,
    });
  }
  const report = JSON.stringify(
    {
      mode: apply ? "apply" : "preview",
      changes: changes.map(({ id, warnings }) => ({
        id,
        warnings,
        warningMessages: migrationWarningMessages(warnings, displayLocale),
      })),
      untouched: ["runtime/providers.json", "runtime/agents.json", "games/*"],
      message: text(displayLocale, "cli.migrated"),
    },
    null,
    2,
  );
  // Validate every conversion before creating backups or replacing any board.
  if (apply) {
    for (const change of changes) await ensureBackup(change.file, change.original);
    const written: typeof changes = [];
    try {
      for (const change of changes) {
        written.push(change);
        await publishBoard(change.file, change.converted);
      }
    } catch (error) {
      const cleanupErrors: unknown[] = [];
      for (const change of written) {
        try {
          await publishBoard(change.file, change.original);
        } catch (rollback) {
          cleanupErrors.push(rollback);
        }
      }
      if (cleanupErrors.length)
        throw new AggregateError(
          [error, ...cleanupErrors],
          "board_config_migration_rollback_failed",
        );
      throw error;
    }
  }
  console.log(report);
}

export async function main(
  argv = process.argv.slice(2),
  display: CliDisplayContext = { locale: "zh-CN", explicit: false },
): Promise<void> {
  const args = takeDisplayArguments(argv, display);
  const values: Record<string, string> = {};
  let apply = false;
  for (let i = 0; i < args.length; i++) {
    if (args[i] === "--apply") {
      apply = true;
      continue;
    }
    if (
      !["--configs-dir", "--source", "--board", "--base"].includes(args[i]) ||
      !args[i + 1] ||
      args[i + 1].startsWith("--")
    )
      throw new Error("config_migration_usage");
    values[args[i]] = args[++i];
  }
  const configDir = resolveCliConfigDirectory(values["--configs-dir"]);
  if (values["--base"] && !["six_player_mvp", "twelve_player_standard"].includes(values["--base"]))
    throw new Error("board_config_legacy_base_unknown");
  if (
    Boolean(values["--source"]) !== Boolean(values["--board"]) ||
    (values["--base"] && !values["--source"])
  )
    throw new Error("config_migration_usage");
  const task = values["--source"]
    ? migrateBoardSource(
        configDir,
        values["--board"],
        values["--source"],
        values["--base"] as BoardName | undefined,
        apply,
        display.locale,
      )
    : migrateBoards(configDir, apply, display.locale);
  await task;
}

if (require.main === module) void runCli(main);

function migrationWarningMessages(
  warnings: readonly MigrationWarningCode[],
  locale: Locale,
): string[] {
  return warnings.map((code) => text(locale, `config.warning.${code}`));
}

import { text, type Locale } from "@ai-werewolf-arena/game-text";
import { ROLE_DEFINITIONS } from "@ai-werewolf-arena/game-catalog";
import type { ResolvedGameSetup } from "./resolve_game_setup";
import type { ResolvedAgentRuntimeProfile } from "./contracts";

function agentSummary(profile: ResolvedAgentRuntimeProfile) {
  return {
    name: profile.name,
    kind: profile.kind,
    providerName: profile.providerName,
    ...(profile.model ? { model: profile.model } : {}),
    customPrompt: Boolean(profile.personalityPrompt),
  };
}

/** Whitelist only: no provider object, env, command arguments, URL or prompt text. */
export function describeResolvedSetup(
  setup: ResolvedGameSetup,
  displayLocale: Locale = setup.context.displayLocale,
) {
  return {
    board: setup.options.board,
    definitionVersion: setup.boardDefinition?.definition.version ?? null,
    ruleset: setup.boardDefinition?.definition.ruleset ?? null,
    rules: setup.boardDefinition?.definition.rules ?? null,
    roles: setup.boardConfig.roleSetups,
    parameters: setup.boardDefinition?.definition.roles ?? {},
    mechanisms: setup.boardDefinition?.definition.mechanisms ?? {},
    defaultAgent: agentSummary(setup.defaultProfile),
    playerAgents: Object.fromEntries(
      Object.entries(setup.playerProfiles).map(([seat, profile]) => [seat, agentSummary(profile)]),
    ),
    roleAgents: Object.fromEntries(
      Object.entries(setup.roleProfiles).map(([role, profile]) => [role, agentSummary(profile)]),
    ),
    players: Object.fromEntries(
      Object.entries(setup.players).map(([seat, entry]) => [
        seat,
        {
          ...(entry.name !== undefined ? { name: entry.name } : {}),
          ...(entry.profile ? { agent: agentSummary(entry.profile) } : {}),
          customPrompt: entry.personalityPrompt !== undefined && entry.personalityPrompt !== null,
          clearedPrompt: entry.personalityPrompt === null,
        },
      ]),
    ),
    context: setup.context,
    executionSupport: { locales: ["zh-CN", "en"], reproducibleSeed: true, mixedTransports: true },
    warnings: setup.warnings,
    warningMessages: setup.warnings.map((warning) =>
      text(displayLocale, "config.warning.locale_prompt_fallback", {
        path: warning.path,
        requested: warning.requestedLocale,
        fallback: warning.fallbackLocale,
      }),
    ),
    audit: setup.audit
      ? {
          agent: agentSummary(setup.audit.profile),
          timeoutMs: setup.audit.timeoutMs,
          concurrency: setup.audit.concurrency,
        }
      : null,
    limits: {
      maxDays: setup.options.maxDays,
      maxRuntimeMs: setup.options.maxRuntimeMs,
      turnTimeoutMs: setup.options.llmTimeoutMs,
    },
    catalog: {
      total: ROLE_DEFINITIONS.length,
      planned: ROLE_DEFINITIONS.filter((item) => item.status === "planned").length,
    },
    sources: {
      board: setup.boardDefinition?.sourceFile ?? "internal_fixture",
      fields: setup.boardDefinition?.fieldSources ?? {},
    },
  };
}

import { promises as fs } from "node:fs";
import path from "node:path";
import { BoardName, BoardOverride, parseBoardOverride } from "../scenarios/board_config_resolver";

/** @deprecated Migration/legacy programmatic compatibility only. Normal CLI loading uses loadBoardDefinition and never probes these fallback paths. */
export async function loadBoardOverride(
  configDir: string,
  board: BoardName,
  log?: (text: string) => void,
): Promise<BoardOverride | null> {
  const root = path.resolve(configDir);
  const candidates = [
    path.join(root, "boards", `${board}.json`),
    path.join(root, `${board}.json`),
    path.join(root, "boards", "game-config.json"),
    path.join(root, "game-config.json"),
  ];

  for (const file of candidates) {
    let contents: string;
    try {
      contents = await fs.readFile(file, "utf8");
    } catch (error) {
      if ((error as NodeJS.ErrnoException).code === "ENOENT") continue;
      throw error;
    }

    let raw: unknown;
    try {
      raw = JSON.parse(contents);
    } catch (error) {
      throw new Error(`board_config_json_invalid: ${file}: ${String(error)}`);
    }
    const override = parseBoardOverride(raw, board);
    if (override) {
      log?.(`[board_config] using override file=${file}`);
      return override;
    }
    if (file.endsWith("game-config.json") && isOtherBoardCollection(raw, board)) continue;
    throw new Error(`board_config_invalid_override: ${file}`);
  }
  return null;
}

function isOtherBoardCollection(value: unknown, board: BoardName): boolean {
  if (!value || typeof value !== "object" || Array.isArray(value)) return false;
  const boards = (value as Record<string, unknown>).boards;
  return (
    !!boards &&
    typeof boards === "object" &&
    !Array.isArray(boards) &&
    !(board in boards) &&
    !("default" in value)
  );
}

/** 将已读取的板子覆盖配置合并为规范化的 BoardConfig。 */
import { z } from "zod";
import {
  ActionWindow,
  BoardConfig,
  HookConfig,
  Role,
  WinCondition,
  WitchSelfHealRule,
} from "../../core/domain/model";
import { getDefaultConfigNormalizerRegistry } from "../../game/mechanisms";
import { sixPlayerMvpConfig } from "./six_player_mvp";
import { twelvePlayerStandardConfig } from "./twelve_player_standard";

/** 已支持的板子标识。 */
export type BoardName = "six_player_mvp" | "twelve_player_standard";
type JsonObject = Record<string, unknown>;
export type BoardOverride = Omit<
  Partial<BoardConfig>,
  "hooks" | "sheriff" | "witch" | "tieBreaker" | "selfDestruct"
> & {
  hooks?: Partial<HookConfig>;
  sheriff?: NonNullable<BoardConfig["sheriff"]>;
  witch?: NonNullable<BoardConfig["witch"]>;
  tieBreaker?: NonNullable<BoardConfig["tieBreaker"]>;
  selfDestruct?: NonNullable<BoardConfig["selfDestruct"]>;
};

type StructuredBoardConfig = {
  board?: {
    size?: number;
    roleSetups?: unknown;
  };
  rules?: {
    winCondition?: unknown;
    winConditions?: unknown;
    hooks?: Partial<HookConfig>;
  };
  mechanisms?: {
    sheriff?: {
      enabled?: boolean;
      initialSeat?: number;
      voteWeight?: number;
      tieBreaker?: unknown;
    };
    selfDestruct?: {
      enabledWindows?: unknown;
    };
    tieBreaker?: {
      exileVote?: unknown;
      wolfKillVote?: unknown;
    };
  };
  roles?: {
    witch?: {
      selfHeal?: unknown;
    };
  };
};

const tieBreaker = z.enum(["min_id", "min_seat", "no_elimination", "no_kill"]);
const hooks = z.strictObject({
  onDaybreak: z.boolean().optional(),
  onPreElection: z.boolean().optional(),
  onPreVote: z.boolean().optional(),
  onPerSpeechGap: z.boolean().optional(),
});
const flatOverride = z.strictObject({
  boardSize: z.number().int().positive().optional(),
  enableSheriff: z.boolean().optional(),
  initialSheriffSeat: z.number().int().positive().optional(),
  winCondition: z.enum(WinCondition).optional(),
  winConditions: z.array(z.enum(WinCondition)).optional(),
  hooks: hooks.optional(),
  selfDestruct: z.strictObject({ enabledWindows: z.array(z.enum(ActionWindow)) }).optional(),
  sheriff: z.strictObject({ voteWeight: z.number().positive().optional() }).optional(),
  witch: z.strictObject({ canSelfHeal: z.enum(WitchSelfHealRule).optional() }).optional(),
  tieBreaker: z
    .strictObject({
      exileVote: tieBreaker.optional(),
      wolfKillVote: tieBreaker.optional(),
      sheriffVote: tieBreaker.optional(),
    })
    .optional(),
  roleSetups: z
    .array(z.strictObject({ role: z.enum(Role), count: z.number().int().nonnegative() }))
    .optional(),
});
const structuredOverride = z.strictObject({
  board: z
    .strictObject({
      size: z.number().int().positive().optional(),
      roleSetups: flatOverride.shape.roleSetups,
    })
    .optional(),
  rules: z
    .strictObject({
      winCondition: flatOverride.shape.winCondition,
      winConditions: flatOverride.shape.winConditions,
      hooks: hooks.optional(),
    })
    .optional(),
  mechanisms: z
    .strictObject({
      sheriff: z
        .strictObject({
          enabled: z.boolean().optional(),
          initialSeat: z.number().int().positive().optional(),
          voteWeight: z.number().positive().optional(),
          tieBreaker: tieBreaker.optional(),
        })
        .optional(),
      selfDestruct: z
        .strictObject({ enabledWindows: z.array(z.enum(ActionWindow)).optional() })
        .optional(),
      tieBreaker: z
        .strictObject({ exileVote: tieBreaker.optional(), wolfKillVote: tieBreaker.optional() })
        .optional(),
    })
    .optional(),
  roles: z
    .strictObject({
      witch: z.strictObject({ selfHeal: z.enum(WitchSelfHealRule).optional() }).optional(),
    })
    .optional(),
});

function validateOverride(schema: z.ZodType, value: unknown): void {
  const result = schema.safeParse(value);
  if (!result.success) {
    const field = result.error.issues[0]?.path.join(".") || "document";
    throw new Error(`board_config_invalid_override_field: ${field}`);
  }
}

function isJsonObject(value: unknown): value is JsonObject {
  return typeof value === "object" && value !== null && !Array.isArray(value);
}

/** 克隆基础板子配置，避免后续 merge 污染静态场景常量。 */
function cloneBoardConfig(config: BoardConfig): BoardConfig {
  return {
    ...config,
    roleSetups: config.roleSetups.map((item) => ({ ...item })),
    hooks: { ...config.hooks },
    ...(config.winConditions ? { winConditions: [...config.winConditions] } : {}),
    ...(config.selfDestruct
      ? {
          selfDestruct: {
            enabledWindows: [...config.selfDestruct.enabledWindows],
          },
        }
      : {}),
    ...(config.sheriff ? { sheriff: { ...config.sheriff } } : {}),
    ...(config.witch ? { witch: { ...config.witch } } : {}),
    ...(config.tieBreaker ? { tieBreaker: { ...config.tieBreaker } } : {}),
  };
}

/** 以 BoardConfig 语义合并覆盖项（保留数组/对象的显式拷贝）。 */
function mergeBoardConfig(base: BoardConfig, override: BoardOverride): BoardConfig {
  return {
    ...base,
    ...override,
    hooks: { ...base.hooks, ...(override.hooks ?? {}) },
    roleSetups: override.roleSetups
      ? override.roleSetups.map((item) => ({ ...item }))
      : base.roleSetups.map((item) => ({ ...item })),
    ...(override.winConditions ? { winConditions: [...override.winConditions] } : {}),
    ...(override.selfDestruct
      ? {
          selfDestruct: {
            enabledWindows: [...override.selfDestruct.enabledWindows],
          },
        }
      : base.selfDestruct
        ? {
            selfDestruct: {
              enabledWindows: [...base.selfDestruct.enabledWindows],
            },
          }
        : {}),
    sheriff: { ...(base.sheriff ?? {}), ...(override.sheriff ?? {}) },
    witch: { ...(base.witch ?? {}), ...(override.witch ?? {}) },
    tieBreaker: { ...(base.tieBreaker ?? {}), ...(override.tieBreaker ?? {}) },
  };
}

/** 以“覆盖层”语义合并 default + board 专属配置。 */
function mergeBoardOverride(base: BoardOverride, override: BoardOverride): BoardOverride {
  return {
    ...base,
    ...override,
    ...(base.hooks || override.hooks
      ? {
          hooks: {
            ...(base.hooks ?? {}),
            ...(override.hooks ?? {}),
          },
        }
      : {}),
    ...(base.sheriff || override.sheriff
      ? {
          sheriff: {
            ...(base.sheriff ?? {}),
            ...(override.sheriff ?? {}),
          },
        }
      : {}),
    ...(base.witch || override.witch
      ? {
          witch: {
            ...(base.witch ?? {}),
            ...(override.witch ?? {}),
          },
        }
      : {}),
    ...(base.tieBreaker || override.tieBreaker
      ? {
          tieBreaker: {
            ...(base.tieBreaker ?? {}),
            ...(override.tieBreaker ?? {}),
          },
        }
      : {}),
    ...(override.roleSetups
      ? {
          roleSetups: override.roleSetups.map((item) => ({ ...item })),
        }
      : base.roleSetups
        ? {
            roleSetups: base.roleSetups.map((item) => ({ ...item })),
          }
        : {}),
    ...(override.winConditions
      ? {
          winConditions: [...override.winConditions],
        }
      : base.winConditions
        ? {
            winConditions: [...base.winConditions],
          }
        : {}),
    ...(override.selfDestruct
      ? {
          selfDestruct: {
            enabledWindows: [...override.selfDestruct.enabledWindows],
          },
        }
      : base.selfDestruct
        ? {
            selfDestruct: {
              enabledWindows: [...base.selfDestruct.enabledWindows],
            },
          }
        : {}),
  };
}

/** 读取对应板子的内置默认配置。 */
function baseBoard(board: BoardName): BoardConfig {
  return board === "twelve_player_standard"
    ? cloneBoardConfig(twelvePlayerStandardConfig)
    : cloneBoardConfig(sixPlayerMvpConfig);
}

/** 判断对象是否为旧版平铺结构。 */
function isBoardOverrideShape(value: unknown): value is BoardOverride {
  if (!isJsonObject(value)) {
    return false;
  }
  const keys = Object.keys(value);
  const supported = new Set([
    "boardSize",
    "enableSheriff",
    "initialSheriffSeat",
    "winCondition",
    "winConditions",
    "hooks",
    "selfDestruct",
    "sheriff",
    "witch",
    "tieBreaker",
    "roleSetups",
  ]);
  return keys.some((key) => supported.has(key));
}

/** 判断对象是否为新版结构化配置。 */
function isStructuredBoardOverrideShape(value: unknown): value is StructuredBoardConfig {
  if (!isJsonObject(value)) {
    return false;
  }
  return ["board", "rules", "mechanisms", "roles"].some((key) => key in value);
}

/** 把新版 `board/rules/mechanisms/roles` 结构映射到 BoardConfig 覆盖层。 */
function parseStructuredBoardOverride(raw: StructuredBoardConfig): BoardOverride {
  const out: BoardOverride = {};

  if (isJsonObject(raw.board)) {
    if (typeof raw.board.size === "number") {
      out.boardSize = raw.board.size;
    }
    if (Array.isArray(raw.board.roleSetups)) {
      out.roleSetups = raw.board.roleSetups as BoardConfig["roleSetups"];
    }
  }

  if (isJsonObject(raw.rules)) {
    if (typeof raw.rules.winCondition === "string") {
      out.winCondition = raw.rules.winCondition as BoardConfig["winCondition"];
    }
    if (Array.isArray(raw.rules.winConditions)) {
      out.winConditions = raw.rules.winConditions as BoardConfig["winConditions"];
    }
    if (isJsonObject(raw.rules.hooks)) {
      out.hooks = {
        ...(typeof raw.rules.hooks.onDaybreak === "boolean"
          ? { onDaybreak: raw.rules.hooks.onDaybreak }
          : {}),
        ...(typeof raw.rules.hooks.onPreElection === "boolean"
          ? { onPreElection: raw.rules.hooks.onPreElection }
          : {}),
        ...(typeof raw.rules.hooks.onPreVote === "boolean"
          ? { onPreVote: raw.rules.hooks.onPreVote }
          : {}),
        ...(typeof raw.rules.hooks.onPerSpeechGap === "boolean"
          ? { onPerSpeechGap: raw.rules.hooks.onPerSpeechGap }
          : {}),
      } as HookConfig;
    }
  }

  if (isJsonObject(raw.mechanisms)) {
    if (isJsonObject(raw.mechanisms.sheriff)) {
      if (typeof raw.mechanisms.sheriff.enabled === "boolean") {
        out.enableSheriff = raw.mechanisms.sheriff.enabled;
      }
      if (typeof raw.mechanisms.sheriff.initialSeat === "number") {
        out.initialSheriffSeat = raw.mechanisms.sheriff.initialSeat;
      }
      if (typeof raw.mechanisms.sheriff.voteWeight === "number") {
        out.sheriff = {
          ...(out.sheriff ?? {}),
          voteWeight: raw.mechanisms.sheriff.voteWeight,
        };
      }
      if (typeof raw.mechanisms.sheriff.tieBreaker === "string") {
        // sheriff.tieBreaker 在新结构里归一到 tieBreaker.sheriffVote。
        out.tieBreaker = {
          ...(out.tieBreaker ?? {}),
          sheriffVote: raw.mechanisms.sheriff.tieBreaker as NonNullable<
            BoardConfig["tieBreaker"]
          >["sheriffVote"],
        };
      }
    }
    if (isJsonObject(raw.mechanisms.selfDestruct)) {
      if (Array.isArray(raw.mechanisms.selfDestruct.enabledWindows)) {
        out.selfDestruct = {
          enabledWindows: raw.mechanisms.selfDestruct.enabledWindows as NonNullable<
            BoardConfig["selfDestruct"]
          >["enabledWindows"],
        };
      }
    }
    if (isJsonObject(raw.mechanisms.tieBreaker)) {
      out.tieBreaker = {
        ...(out.tieBreaker ?? {}),
        ...(typeof raw.mechanisms.tieBreaker.exileVote === "string"
          ? {
              exileVote: raw.mechanisms.tieBreaker.exileVote as NonNullable<
                BoardConfig["tieBreaker"]
              >["exileVote"],
            }
          : {}),
        ...(typeof raw.mechanisms.tieBreaker.wolfKillVote === "string"
          ? {
              wolfKillVote: raw.mechanisms.tieBreaker.wolfKillVote as NonNullable<
                BoardConfig["tieBreaker"]
              >["wolfKillVote"],
            }
          : {}),
      };
    }
  }

  if (isJsonObject(raw.roles)) {
    if (isJsonObject(raw.roles.witch) && typeof raw.roles.witch.selfHeal === "string") {
      out.witch = {
        ...(out.witch ?? {}),
        canSelfHeal: raw.roles.witch.selfHeal as NonNullable<BoardConfig["witch"]>["canSelfHeal"],
      };
    }
  }

  return out;
}

/** 统一解析“单个配置块”成覆盖层（兼容新旧两种结构）。 */
function toBoardOverride(value: unknown): BoardOverride | null {
  if (isBoardOverrideShape(value)) {
    validateOverride(flatOverride, value);
    return value as BoardOverride;
  }
  if (isStructuredBoardOverrideShape(value)) {
    validateOverride(structuredOverride, value);
    return parseStructuredBoardOverride(value);
  }
  return null;
}

/** 从 json 根对象提取目标板子的覆盖配置（含 boards/default 合并）。 */
export function parseBoardOverride(raw: unknown, board: BoardName): BoardOverride | null {
  const direct = toBoardOverride(raw);
  if (direct) {
    return direct;
  }
  if (!isJsonObject(raw)) {
    return null;
  }

  if ("boards" in raw || "default" in raw) {
    validateOverride(
      z.strictObject({
        boards: z
          .record(
            z.string().regex(/^[a-z][a-z0-9_-]*$/),
            z.union([flatOverride, structuredOverride]),
          )
          .optional(),
        default: z.union([flatOverride, structuredOverride]).optional(),
      }),
      raw,
    );
  } else {
    const allowed = new Set([board, "six_player_mvp", "twelve_player_standard"]);
    for (const [key, value] of Object.entries(raw)) {
      if (!allowed.has(key)) throw new Error("board_config_invalid_override_field: document");
      validateOverride(z.union([flatOverride, structuredOverride]), value);
    }
  }

  const boardsEntry = isJsonObject(raw.boards) ? raw.boards[board] : undefined;
  const boardOverride = toBoardOverride(boardsEntry);
  if (boardOverride) {
    const defaultOverride = toBoardOverride(raw.default);
    if (!defaultOverride) {
      return boardOverride;
    }
    return mergeBoardOverride(defaultOverride, boardOverride);
  }

  const keyedBoardOverride = toBoardOverride(raw[board]);
  if (keyedBoardOverride) {
    return keyedBoardOverride;
  }
  return null;
}

/** 合并并规范化板子配置；文件查找由加载层负责。 */
export function resolveBoardConfig(
  board: BoardName,
  override: BoardOverride | null = null,
): BoardConfig {
  const base = baseBoard(board);
  const merged = override ? mergeBoardConfig(base, override) : base;
  return getDefaultConfigNormalizerRegistry().normalize(merged);
}

/**
 * 场景板子统一导出入口。
 */
export { sixPlayerMvpConfig } from "./six_player_mvp";
export { twelvePlayerStandardConfig } from "./twelve_player_standard";
export { resolveBoardConfig } from "./board_config_resolver";

