/**
 * 从指定配置目录顺序读取 providers、agents、具名 game 与可选审计文件，输出已校验 RuntimeConfig。
 * 本模块拥有文件读取和 JSON 错误转换；配置解析由 parseRuntimeConfig 执行，Agent／会话资源由运行装配持有。
 * 必填文件缺失和其它 I/O 失败直接传播；仅审计文件缺失可省略，不自动探测旧目录、加载 .env 或缓存配置。
 */
import { promises as fs } from "node:fs";
import * as path from "node:path";
import type { RuntimeConfig } from "./contracts";
import { parseRuntimeConfig } from "./parse_config";

export interface RuntimeConfigLoadOptions {
  configDir: string;
  gameName: string;
  environment?: NodeJS.ProcessEnv;
}

async function readJsonFile(filePath: string, label: string): Promise<unknown> {
  let raw: string;
  try {
    raw = await fs.readFile(filePath, "utf8");
  } catch (error) {
    const code = (error as NodeJS.ErrnoException).code;
    if (code === "ENOENT") throw new Error(`runtime_config_file_missing: ${label} -> ${filePath}`);
    throw error;
  }
  try {
    return JSON.parse(raw);
  } catch {
    // JSON 引擎错误可能夹带 provider 密钥值；这里只保留文件类别，避免原内容进入报错。
    throw new Error(`runtime_config_json_invalid: ${label}`);
  }
}

/** 只有缺失文件才省略；坏 JSON、权限问题等失败仍中断配置加载。 */
async function readOptionalJsonFile(filePath: string, label: string): Promise<unknown | undefined> {
  try {
    return await readJsonFile(filePath, label);
  } catch (error) {
    if ((error as Error).message.startsWith("runtime_config_file_missing:")) return undefined;
    throw error;
  }
}

export async function loadRuntimeConfig(options: RuntimeConfigLoadOptions): Promise<RuntimeConfig> {
  if (!options.configDir.trim()) throw new Error("runtime_config_missing_configs_dir");
  if (!/^[a-z][a-z0-9_-]*$/.test(options.gameName)) {
    throw new Error(`runtime_config_game_name_invalid: ${options.gameName}`);
  }
  // 所有相对路径以本次显式目录解析；顺序等待各文件，保持原错误先后次序。
  const configRoot = path.resolve(options.configDir);
  const runtimeDir = path.join(configRoot, "runtime");
  return parseRuntimeConfig({
    providers: await readJsonFile(path.join(runtimeDir, "providers.json"), "providers"),
    agents: await readJsonFile(path.join(runtimeDir, "agents.json"), "agents"),
    game: await readJsonFile(
      path.join(configRoot, "games", `${options.gameName}.json`),
      `games.${options.gameName}`,
    ),
    debugSummary: await readOptionalJsonFile(
      path.join(runtimeDir, "debug_summary.json"),
      "debugSummary",
    ),
    environment: options.environment,
  });
}

/**
 * 负责合并已解析配置、运行参数和座位／角色 Agent 选择。输入为公开配置与 CLI 覆盖；
 * 输出为完整对局设置、逐玩家配置和语言回退诊断。仅选择已登记角色，不创建对局、
 * 读取认证或授予行动权限；名字和人格保留原文，不参与模型选择。
 */
import type { BoardConfig } from "../../core";
import type {
  GameConfig,
  GameAgentSelection,
  ResolvedAgentRuntimeProfile,
  ResolvedAuditConfig,
  RuntimeConfig,
  PlayerConfig,
} from "./contracts";
import type { Locale } from "@ai-werewolf-arena/game-contract";
import {
  resolveBoardConfig,
  type BoardName,
  type BoardOverride,
} from "../scenarios/board_config_resolver";
import { type ResolvedBoardDefinition } from "./board_definition";
import { getDefaultRoleCatalog } from "../../game/mechanisms/roles/role-catalog-assembly";
import { Role } from "../../core/domain/identity";

export interface RunGameOptions {
  board: string;
  maxDays: number;
  maxRuntimeMs: number;
  llmTimeoutMs: number;
  trace: boolean;
  printAllEvents: boolean;
  printChat: boolean;
  streamEvents: boolean;
  color: boolean;
  printLlmIo: boolean;
  printThinking: boolean;
  printPrivateEvents: boolean;
  recordRootDir?: string;
}

export interface GameSetupWarning {
  code: "locale_prompt_fallback";
  path: string;
  requestedLocale: Locale;
  fallbackLocale: Locale;
}

export interface ResolvedPlayerConfig {
  name?: string;
  profile?: ResolvedAgentRuntimeProfile;
  personalityPrompt?: string | null;
}

/** runner 的完整输入：已解析板子、逐玩家／角色 profile 与可选审计；不携带运行句柄或已分配身份。 */
export interface ResolvedGameSetup {
  options: RunGameOptions;
  boardConfig: BoardConfig;
  defaultProfile: ResolvedAgentRuntimeProfile;
  playerProfiles: Readonly<Record<string, ResolvedAgentRuntimeProfile>>;
  roleProfiles: Readonly<Record<string, ResolvedAgentRuntimeProfile>>;
  audit: ResolvedAuditConfig | null;
  boardDefinition?: ResolvedBoardDefinition;
  context: { locale: Locale; displayLocale: Locale; seed?: string };
  players: Readonly<Record<string, ResolvedPlayerConfig>>;
  warnings: readonly GameSetupWarning[];
}

/** 分配身份后按 players 显式 Agent→playerAgents→roleAgents→默认值选择；独立人格最后覆盖，null 清除继承。 */
export function resolvePlayerProfile(
  setup: ResolvedGameSetup,
  actorId: number,
  role?: Role,
): ResolvedAgentRuntimeProfile {
  const player = setup.players[String(actorId)];
  const selected =
    player?.profile ??
    setup.playerProfiles[String(actorId)] ??
    (role ? setup.roleProfiles[role] : undefined) ??
    setup.defaultProfile;
  return player?.personalityPrompt !== undefined
    ? { ...selected, personalityPrompt: player.personalityPrompt ?? undefined }
    : selected;
}

export function resolveGameBoard(
  runtime: RuntimeConfig,
  overrides: Partial<RunGameOptions> = {},
): string {
  const board = overrides.board ?? runtime.game.board ?? "six_player_mvp";
  if (!/^[a-z][a-z0-9_-]*$/.test(board)) {
    throw new Error(`runtime_config_board_invalid: ${board}`);
  }
  return board;
}

export function resolveAgentProfileByName(
  runtime: RuntimeConfig,
  agentName?: string,
): ResolvedAgentRuntimeProfile {
  const selected = agentName ?? runtime.agents.default;
  const entry = runtime.agents.items[selected];
  if (!entry) throw new Error(`runtime_config_agent_not_found: ${selected}`);
  const provider = runtime.providers.items[entry.provider];
  if (!provider)
    throw new Error(
      `runtime_config_agent_provider_not_found: agent=${selected} provider=${entry.provider}`,
    );
  if (entry.kind === "acp") {
    return {
      name: selected,
      providerName: entry.provider,
      provider,
      kind: "acp",
      spawnArgs: entry.spawnArgs,
      sessionReuse: entry.sessionReuse,
      actionTransport: entry.actionTransport ?? "mcp",
      personalityPrompt: entry.personalityPrompt,
    };
  }
  return {
    name: selected,
    providerName: entry.provider,
    provider,
    kind: "llm",
    model: entry.model,
    temperature: entry.temperature,
    maxTokens: entry.maxTokens,
    reasoningEffort: entry.reasoningEffort,
    thinkingEnabled: entry.thinkingEnabled,
    personalityPrompt: entry.personalityPrompt,
  };
}

function resolveSelections(
  runtime: RuntimeConfig,
  selections: Record<string, GameAgentSelection> | undefined,
): Record<string, ResolvedAgentRuntimeProfile> {
  return Object.fromEntries(
    Object.entries(selections ?? {}).map(([key, selection]) => {
      const name = typeof selection === "string" ? selection : selection.agent;
      const profile = resolveAgentProfileByName(runtime, name);
      const spawnArgs = typeof selection === "object" ? selection.spawnArgs : undefined;
      const personalityPrompt =
        typeof selection === "object" ? selection.personalityPrompt : undefined;
      return [
        key,
        {
          ...profile,
          ...(profile.kind === "acp" && spawnArgs?.length
            ? { spawnArgs: [...(profile.spawnArgs ?? []), ...spawnArgs] }
            : {}),
          ...(personalityPrompt !== undefined ? { personalityPrompt } : {}),
        },
      ];
    }),
  );
}

export function resolveGameSetup(
  runtime: RuntimeConfig,
  overrides: Partial<RunGameOptions> = {},
  boardOverride: BoardOverride | ResolvedBoardDefinition | null = null,
): ResolvedGameSetup {
  if (
    !runtime.providers.items[runtime.providers.default] ||
    !runtime.agents.items[runtime.agents.default]
  ) {
    throw new Error("runtime_config_missing_provider_or_agent_defaults");
  }
  const game = runtime.game;
  // 空值合并让显式 false 保持有效；CLI 覆盖只作用于这里声明的运行选项，语言和 seed 仍由 game 提供。
  const options: RunGameOptions = {
    board: resolveGameBoard(runtime, overrides),
    maxDays: overrides.maxDays ?? game.maxDays ?? 10,
    maxRuntimeMs: overrides.maxRuntimeMs ?? game.maxRuntimeMs ?? 30000,
    llmTimeoutMs: overrides.llmTimeoutMs ?? game.llmTimeoutMs ?? 30000,
    trace: overrides.trace ?? game.trace ?? false,
    printAllEvents: overrides.printAllEvents ?? game.printAllEvents ?? false,
    printChat: overrides.printChat ?? game.printChat ?? false,
    streamEvents: overrides.streamEvents ?? game.streamEvents ?? true,
    color: overrides.color ?? game.color ?? true,
    printLlmIo: overrides.printLlmIo ?? game.printLlmIo ?? false,
    printThinking: overrides.printThinking ?? game.printThinking ?? false,
    printPrivateEvents: overrides.printPrivateEvents ?? game.printPrivateEvents ?? true,
    recordRootDir: overrides.recordRootDir ?? game.recordRootDir,
  };
  const auditConfig = runtime.debugSummary?.agent;
  for (const key of ["maxDays", "maxRuntimeMs", "llmTimeoutMs"] as const) {
    if (!Number.isSafeInteger(options[key]) || options[key] <= 0)
      throw new Error(`runtime_config_positive_integer_invalid: game.${key}`);
  }
  // 具名定义必须与选定板子一致；没有定义时只接受原两项内置板子，不由 runner 猜测支持组合。
  const boardDefinition =
    boardOverride && "definition" in boardOverride ? boardOverride : undefined;
  if (boardDefinition && boardDefinition.definition.id !== options.board)
    throw new Error("runtime_config_board_definition_mismatch");
  if (
    !boardDefinition &&
    options.board !== "six_player_mvp" &&
    options.board !== "twelve_player_standard"
  ) {
    throw new Error(`runtime_config_board_definition_required: ${options.board}`);
  }
  const boardConfig =
    boardDefinition?.config ??
    resolveBoardConfig(options.board as BoardName, boardOverride as BoardOverride | null);
  validateGameBindings(game, boardConfig);
  const locale = game.locale ?? "zh-CN";
  const warnings: GameSetupWarning[] = [];
  const players = resolvePlayers(runtime, game.players, locale, warnings);
  return {
    options,
    boardConfig,
    ...(boardDefinition ? { boardDefinition } : {}),
    context: {
      locale,
      displayLocale: game.displayLocale ?? locale,
      ...(game.seed ? { seed: game.seed } : {}),
    },
    players,
    warnings,
    defaultProfile: resolveAgentProfileByName(runtime, game.agent),
    playerProfiles: resolveSelections(runtime, game.playerAgents),
    roleProfiles: resolveSelections(runtime, game.roleAgents),
    // 只有显式 enabled:false 才关闭审计；省略配置保原默认值，创建与失败处理留给运行／审计 owner。
    audit:
      auditConfig?.enabled === false
        ? null
        : {
            profile: resolveAgentProfileByName(runtime, auditConfig?.agentName ?? game.agent),
            timeoutMs: auditConfig?.timeoutMs ?? 15000,
            maxAttempts: Math.max(1, auditConfig?.maxAttempts ?? 2),
            concurrency: Math.max(1, auditConfig?.concurrency ?? 4),
            publicMaxItems: Math.max(60, auditConfig?.publicMaxItems ?? 200),
            maxItems: Math.max(50, auditConfig?.maxItems ?? 200),
            playerMaxItems: Math.max(60, auditConfig?.playerMaxItems ?? 120),
          },
  };
}

export function validateGameBindings(game: GameConfig, board: BoardConfig): void {
  const catalog = getDefaultRoleCatalog();
  for (const entry of board.roleSetups) catalog.requireMetadata(entry.role);
  const present = new Set(
    board.roleSetups.filter((entry) => entry.count > 0).map((entry) => entry.role),
  );
  for (const key of Object.keys(game.roleAgents ?? {})) {
    if (!catalog.metadata(key as Role) || !present.has(key as Role))
      throw new Error(`runtime_config_role_binding_invalid: ${key}`);
  }
  for (const key of Object.keys(game.playerAgents ?? {})) {
    if (
      !/^[1-9]\d*$/.test(key) ||
      Number(key) > board.boardSize ||
      !Number.isSafeInteger(Number(key))
    ) {
      throw new Error(`runtime_config_player_binding_invalid: ${key}`);
    }
  }
  // 同一座位同时出现于新 players 和旧 playerAgents 会拒绝，避免隐式优先级掩盖配置冲突。
  for (const key of Object.keys(game.players ?? {})) {
    if (
      !/^[1-9]\d*$/.test(key) ||
      Number(key) > board.boardSize ||
      !Number.isSafeInteger(Number(key))
    )
      throw new Error(`runtime_config_player_binding_invalid: ${key}`);
    if (game.playerAgents && key in game.playerAgents)
      throw new Error(`runtime_config_player_binding_conflict: ${key}`);
  }
}

function resolvePlayers(
  runtime: RuntimeConfig,
  entries: Record<string, PlayerConfig> | undefined,
  locale: Locale,
  warnings: GameSetupWarning[],
): Record<string, ResolvedPlayerConfig> {
  return Object.fromEntries(
    Object.entries(entries ?? {}).map(([seat, entry]) => {
      let profile = entry.agent ? resolveAgentProfileByName(runtime, entry.agent) : undefined;
      if (profile?.kind === "acp" && entry.spawnArgs?.length)
        profile = { ...profile, spawnArgs: [...(profile.spawnArgs ?? []), ...entry.spawnArgs] };
      let personalityPrompt: string | null | undefined =
        entry.personalityPrompt === null ? null : undefined;
      if (typeof entry.personalityPrompt === "string") personalityPrompt = entry.personalityPrompt;
      // 语言表优先本语言，再优先中文、最后英文；只产生回退诊断，不翻译用户人格文本。
      else if (entry.personalityPrompt) {
        if (entry.personalityPrompt[locale]) personalityPrompt = entry.personalityPrompt[locale];
        else {
          const fallback = entry.personalityPrompt["zh-CN"] ? "zh-CN" : "en";
          personalityPrompt = entry.personalityPrompt[fallback];
          warnings.push({
            code: "locale_prompt_fallback",
            path: `players.${seat}.personalityPrompt`,
            requestedLocale: locale,
            fallbackLocale: fallback,
          });
        }
      }
      return [
        seat,
        {
          ...(entry.name !== undefined ? { name: entry.name } : {}),
          ...(profile ? { profile } : {}),
          ...(personalityPrompt !== undefined ? { personalityPrompt } : {}),
        },
      ];
    }),
  );
}

/**
 * 负责 CLI 展示语言参数与顶层错误呈现。输入为原 argv 和可更新的展示上下文，输出剩余参数及本地化进程错误。
 * 本入口只组织显示／退出，不解析游戏规则；原错误码与明确语言优先级保持。
 */
import { isLocale } from "@ai-werewolf-arena/game-contract";
import { errorMessage, text, type Locale } from "@ai-werewolf-arena/game-text";
import { describeError } from "../../utils/error_diagnostic";
import { configDiagnostic } from "../config/error_codes";
import { COMMAND_ERROR_CODES } from "./error_codes";

/** 展示上下文只归一次调用，不改变游戏或进程环境。 */
export interface CliDisplayContext {
  locale: Locale;
  explicit: boolean;
}
export function takeDisplayArguments(args: string[], context: CliDisplayContext): string[] {
  const rest: string[] = [];
  for (let index = 0; index < args.length; index++) {
    if (args[index] !== "--display-locale") {
      rest.push(args[index]);
      continue;
    }
    const value = args[++index];
    if (!isLocale(value)) throw new Error("runtime_cli_locale_invalid");
    context.locale = value;
    context.explicit = true;
  }
  return rest;
}
export function cliFailure(error: unknown, locale: Locale) {
  const configuration = configDiagnostic(error);
  let message: unknown;
  try {
    message =
      error && typeof error === "object"
        ? Object.getOwnPropertyDescriptor(error, "message")?.value
        : undefined;
  } catch {
    /* 无法透视的外来错误。 */
  }
  const candidate = typeof message === "string" ? message.split(":", 1)[0] : "command_failed";
  const code =
    configuration.code !== "config_check_failed"
      ? configuration.code
      : COMMAND_ERROR_CODES.includes(candidate as (typeof COMMAND_ERROR_CODES)[number])
        ? candidate
        : "command_failed";
  const diagnostic = describeError(error);
  const explanation =
    code === "runtime_cli_locale_invalid"
      ? text(locale, "cli.locale_invalid")
      : code === "runtime_cli_boolean_invalid"
        ? text(locale, "cli.boolean_invalid")
        : code === "runtime_cli_option_unknown"
          ? text(locale, "cli.option_unknown")
          : code === "runtime_cli_value_missing"
            ? text(locale, "cli.value_missing")
            : code.endsWith("_usage")
              ? text(locale, "cli.usage_invalid")
              : code === "runtime_locale_execution_not_enabled" ||
                  code === "reproduction_locale_not_enabled"
                ? text(locale, "cli.locale_gate")
                : code.startsWith("runtime_config_") || code.startsWith("board_config_")
                  ? text(locale, "cli.configuration_failed", { code })
                  : code.startsWith("reproduction_")
                    ? text(locale, "cli.reproduction_failed", { code })
                    : code.startsWith("replay_")
                      ? text(locale, "cli.replay_failed", { code })
                      : code.startsWith("simulation_")
                        ? text(locale, "cli.simulation_failed", { code })
                        : errorMessage(locale, diagnostic.code);
  return {
    code,
    ...(configuration.path ? { path: configuration.path } : {}),
    diagnostic,
    message: explanation,
  };
}
/** 仅处理 CLI 输出／退出；程序调用仍沿原函数抛出原错误。 */
export async function runCli(
  command: (args: string[], display: CliDisplayContext) => Promise<void>,
  args = process.argv.slice(2),
): Promise<void> {
  const display: CliDisplayContext = { locale: "zh-CN", explicit: false };
  try {
    await command(args, display);
  } catch (error) {
    console.error(JSON.stringify(cliFailure(error, display.locale)));
    process.exitCode = 1;
  }
}

/**
 * 负责校验和规范化公开板子格式。输入为纯公开 JSON 与已登记角色声明；输出为原 BoardConfig、诊断和反向序列化配置。解析拥有字段／默认值规范化，规则集拥有有限支持裁决；不读取认证、执行对局或授予行动租约。
 */
import { boardPresetViolation } from "../../rulesets";
/** 唯一公开板子格式；未知字段和未注册角色保持原拒绝。 */
import { supportsWallRoles } from "../../game/mechanisms/events/wall_notes/authority";
import { z } from "zod";
import { RULESET } from "@ai-werewolf-arena/game-catalog";
import { ROLE_IDS, isRoleId } from "@ai-werewolf-arena/game-contract";
import { ActionWindow, Camp, Role, WinCondition, type BoardConfig } from "../../core/domain/model";
import { getDefaultRoleCatalog } from "../../game/mechanisms/roles/role-catalog-assembly";
import {
  EVENT_PACK_IDS,
  DEATH_REVEAL_POLICIES,
  LAST_WORDS_POLICIES,
  SHERIFF_BADGE_POLICIES,
  SHERIFF_ELECTION_POLICIES,
  EXILE_VOTE_POLICIES,
} from "../../core/domain/board";
import { boardConfigSchema } from "../../core/domain/board_schema";

export const CONFIG_ID_PATTERN = /^[a-z][a-z0-9_-]*$/;
export const MAX_BOARD_PLAYERS = 128;
export const boardIdSchema = z.string().regex(CONFIG_ID_PATTERN);
const safePositive = z.number().int().positive().max(Number.MAX_SAFE_INTEGER);
const hooks = z.strictObject({
  onDaybreak: z.boolean(),
  onPreElection: z.boolean(),
  onPreVote: z.boolean(),
  onPerSpeechGap: z.boolean(),
});
const schema = z.strictObject({
  version: z.literal(2),
  id: boardIdSchema,
  ruleset: z.strictObject({ id: z.literal(RULESET.id), version: z.literal(RULESET.version) }),
  board: z.strictObject({
    size: safePositive.max(MAX_BOARD_PLAYERS),
    roleSetups: z
      .array(
        z.strictObject({
          role: z.enum(ROLE_IDS as [string, ...string[]]),
          count: safePositive.max(MAX_BOARD_PLAYERS),
        }),
      )
      .min(1),
  }),
  rules: z.strictObject({ winConditions: z.array(z.enum(WinCondition)).min(1), hooks }),
  mechanisms: z.strictObject({
    eventPack: z.enum(EVENT_PACK_IDS).optional(),
    disclosure: z
      .strictObject({ deathRevealPolicy: z.enum(DEATH_REVEAL_POLICIES).default("awa_hidden_v1") })
      .default({ deathRevealPolicy: "awa_hidden_v1" }),
    lastWords: z
      .strictObject({ policy: z.enum(LAST_WORDS_POLICIES).default("awa_initial_wave_v1") })
      .default({ policy: "awa_initial_wave_v1" }),
    sheriff: z.strictObject({
      enabled: z.boolean(),
      electionPolicy: z.enum(SHERIFF_ELECTION_POLICIES).default("awa_final_candidates_v1"),
      badgePolicy: z.enum(SHERIFF_BADGE_POLICIES).default("awa_next_seat_v1"),
      initialSeat: safePositive.optional(),
      voteWeight: z.number().finite().positive().default(1.5),
      tieBreaker: z.enum(["min_id", "min_seat", "no_elimination"]).default("min_seat"),
    }),
    voting: z
      .strictObject({ exilePolicy: z.enum(EXILE_VOTE_POLICIES).default("awa_direct_v1") })
      .default({ exilePolicy: "awa_direct_v1" }),
    selfDestruct: z.strictObject({ enabledWindows: z.array(z.enum(ActionWindow)) }),
    tieBreaker: z.strictObject({
      exileVote: z.enum(["min_id", "no_elimination"]),
      wolfKillVote: z.enum(["min_id", "no_kill"]),
    }),
  }),
  roles: z.record(z.string(), z.unknown()).default({}),
});

export type BoardDefinition = z.infer<typeof schema>;
export interface ResolvedBoardDefinition {
  definition: BoardDefinition;
  config: BoardConfig;
  sourceFile?: string;
  fieldSources: Readonly<Record<string, "explicit" | "default">>;
}

export class BoardConfigurationError extends Error {
  constructor(
    readonly code: string,
    readonly fieldPath: string,
  ) {
    super(`${code}: ${fieldPath}`);
  }
}
function fail(code: string, path: string): never {
  throw new BoardConfigurationError(code, path);
}

export function parseBoardDefinition(raw: unknown, expectedId?: string): ResolvedBoardDefinition {
  const result = schema.safeParse(raw);
  if (!result.success) {
    const issue = result.error.issues[0];
    const key = issue.code === "unrecognized_keys" ? issue.keys[0] : undefined;
    fail(
      "board_config_invalid_field",
      [...issue.path, ...(key ? [key] : [])].join(".") || "document",
    );
  }
  const definition = result.data;
  if (expectedId !== undefined && definition.id !== expectedId)
    fail("board_config_id_mismatch", "id");
  const catalog = getDefaultRoleCatalog();
  const seen = new Set<string>();
  let total = 0;
  for (const [index, entry] of definition.board.roleSetups.entries()) {
    if (!isRoleId(entry.role) || !catalog.metadata(entry.role as Role))
      fail("board_config_role_not_implemented", `board.roleSetups.${index}.role`);
    if (seen.has(entry.role)) fail("board_config_duplicate_role", `board.roleSetups.${index}.role`);
    const maximum = catalog.requireMetadata(entry.role as Role).maxCount;
    if (maximum !== undefined && entry.count > maximum)
      fail("board_config_invalid_field", `board.roleSetups.${index}.count`);
    seen.add(entry.role);
    total += entry.count;
  }
  if (total !== definition.board.size) fail("board_config_role_count_mismatch", "board.roleSetups");
  if (
    definition.board.roleSetups.some((row) => row.role === "shapeshifter") &&
    (definition.board.size < 6 ||
      definition.board.roleSetups
        .filter((row) => row.role === "wolf")
        .reduce((n, row) => n + row.count, 0) < 2 ||
      !definition.board.roleSetups.some(
        (row) => row.role !== "shapeshifter" && catalog.getCamp(row.role as Role) === Camp.Good,
      ))
  )
    fail("board_config_role_combination_not_supported", "board.roleSetups");
  if (definition.board.roleSetups.some((row) => row.role === "thief")) {
    const wolves = definition.board.roleSetups
        .filter((row) => row.role === "wolf")
        .reduce((n, row) => n + row.count, 0),
      good = definition.board.roleSetups
        .filter((row) => row.role !== "thief" && catalog.getCamp(row.role as Role) === Camp.Good)
        .reduce((n, row) => n + row.count, 0);
    if (wolves < 2 || good < 2)
      fail("board_config_role_combination_not_supported", "board.roleSetups");
  }
  if (
    definition.board.roleSetups.some((row) => row.role === "wild_child") &&
    !definition.board.roleSetups.some(
      (row) => row.role !== "wild_child" && catalog.getCamp(row.role as Role) === Camp.Good,
    )
  )
    fail("board_config_role_combination_not_supported", "board.roleSetups");
  if (
    definition.board.roleSetups.some((row) => row.role === "lonely_girl") &&
    (definition.board.size < 6 ||
      !definition.board.roleSetups.some((row) => row.role === "wolf") ||
      !definition.board.roleSetups.some(
        (row) => row.role !== "lonely_girl" && catalog.getCamp(row.role as Role) === Camp.Good,
      ))
  )
    fail("board_config_role_combination_not_supported", "board.roleSetups");
  const profiles = definition.board.roleSetups.map((entry) =>
    catalog.requireMetadata(entry.role as Role),
  );
  for (const profile of profiles) {
    if (
      profile.supportedBoardRoles &&
      definition.board.roleSetups.some(
        (entry) => !profile.supportedBoardRoles!.includes(entry.role as Role),
      )
    ) {
      fail("board_config_role_combination_not_supported", "board.roleSetups");
    }
  }
  if (
    !profiles.some((item) => item.camp === Camp.Wolf) ||
    !profiles.some((item) => item.camp === Camp.Good)
  ) {
    fail("board_config_requires_good_and_wolf", "board.roleSetups");
  }
  for (const profile of profiles)
    if (
      profile.supportedWinConditions &&
      definition.rules.winConditions.some(
        (condition) => !profile.supportedWinConditions!.includes(condition),
      )
    )
      fail("board_config_role_win_condition_not_supported", "rules.winConditions");
  if (new Set(definition.rules.winConditions).size !== definition.rules.winConditions.length)
    fail("board_config_duplicate_win_condition", "rules.winConditions");
  if (
    definition.mechanisms.eventPack &&
    !supportsWallRoles(definition.board.roleSetups.map((e) => e.role as Role))
  )
    fail("board_config_role_combination_not_supported", "mechanisms.eventPack");
  const sheriff = definition.mechanisms.sheriff;
  if (sheriff.initialSeat && sheriff.initialSeat > total)
    fail("board_config_seat_out_of_range", "mechanisms.sheriff.initialSeat");
  if (
    !sheriff.enabled &&
    (sheriff.initialSeat ||
      sheriff.voteWeight !== 1.5 ||
      sheriff.tieBreaker !== "min_seat" ||
      sheriff.electionPolicy !== "awa_final_candidates_v1" ||
      sheriff.badgePolicy !== "awa_next_seat_v1")
  ) {
    fail("board_config_disabled_mechanism_parameters", "mechanisms.sheriff");
  }
  const windows = definition.mechanisms.selfDestruct.enabledWindows;
  if (new Set(windows).size !== windows.length)
    fail("board_config_duplicate_window", "mechanisms.selfDestruct.enabledWindows");
  const windowHooks = {
    [ActionWindow.OnPreVote]: "onPreVote",
    [ActionWindow.OnDaybreak]: "onDaybreak",
    [ActionWindow.OnPreElection]: "onPreElection",
    [ActionWindow.OnPerSpeechGap]: "onPerSpeechGap",
  } as const;
  for (const window of windows)
    if (!definition.rules.hooks[windowHooks[window]])
      fail("board_config_window_hook_disabled", `rules.hooks.${windowHooks[window]}`);
  if (definition.rules.winConditions.includes(WinCondition.SlaughterSide)) {
    if (
      !profiles.some((item) => item.goodSide === "god") ||
      !profiles.some((item) => item.goodSide === "villager")
    ) {
      fail("board_config_slaughter_side_requires_both_sides", "rules.winConditions");
    }
  }
  let config: BoardConfig = {
    boardSize: total,
    roleSetups: definition.board.roleSetups.map((entry) => ({
      role: entry.role as Role,
      count: entry.count,
    })),
    winConditions: [...definition.rules.winConditions],
    hooks: { ...definition.rules.hooks },
    enableSheriff: sheriff.enabled,
    ...(sheriff.initialSeat ? { initialSheriffSeat: sheriff.initialSeat } : {}),
    ...(sheriff.enabled
      ? {
          sheriff: {
            voteWeight: sheriff.voteWeight,
            electionPolicy: sheriff.electionPolicy,
            badgePolicy: sheriff.badgePolicy,
          },
        }
      : {}),
    selfDestruct: { enabledWindows: [...windows] },
    ...(definition.mechanisms.eventPack
      ? { events: { pack: definition.mechanisms.eventPack } }
      : {}),
    voting: { ...definition.mechanisms.voting },
    disclosure: { ...definition.mechanisms.disclosure },
    lastWords: { ...definition.mechanisms.lastWords },
    tieBreaker: {
      ...definition.mechanisms.tieBreaker,
      ...(sheriff.enabled ? { sheriffVote: sheriff.tieBreaker } : {}),
    },
  };
  for (const [id, value] of Object.entries(definition.roles)) {
    if (!seen.has(id)) fail("board_config_role_parameters_without_role", `roles.${id}`);
    const contribution = catalog.requireRuntime(id as Role).configuration;
    if (!contribution) fail("board_config_role_parameters_not_supported", `roles.${id}`);
    const parsed = contribution.schema.safeParse(value);
    if (!parsed.success) {
      const issue = parsed.error.issues[0];
      const unknown = issue.code === "unrecognized_keys" ? issue.keys[0] : undefined;
      fail(
        "board_config_invalid_field",
        ["roles", id, ...issue.path, ...(unknown ? [unknown] : [])].join("."),
      );
    }
    definition.roles[id] = parsed.data;
    config = contribution.apply(config, parsed.data);
  }
  for (const id of seen) {
    const contribution = catalog.requireRuntime(id as Role).configuration;
    if (contribution && !(id in definition.roles)) {
      const defaults = contribution.schema.parse(contribution.defaults);
      definition.roles[id] = defaults;
      config = contribution.apply(config, defaults);
    }
  }
  const presetViolation = boardPresetViolation(config);
  if (presetViolation) fail(`board_config_${presetViolation}`, "board");
  const fieldSources: Record<string, "explicit" | "default"> = {};
  const recordSources = (value: unknown, original: unknown, prefix: string) => {
    if (value && typeof value === "object" && !Array.isArray(value)) {
      for (const [key, entry] of Object.entries(value)) {
        const prior =
          original && typeof original === "object"
            ? (original as Record<string, unknown>)[key]
            : undefined;
        recordSources(entry, prior, prefix ? `${prefix}.${key}` : key);
      }
    } else fieldSources[prefix] = original === undefined ? "default" : "explicit";
  };
  recordSources(definition, raw, "");
  return { definition, config, fieldSources };
}

/** 公开板子只含实际角色的参数；Tape 仍保留完整内部板子。 */
export function boardDefinitionFromConfig(id: string, config: BoardConfig): BoardDefinition {
  const valid = boardConfigSchema.safeParse(config);
  if (!valid.success) {
    const issue = valid.error.issues[0];
    const key = issue.code === "unrecognized_keys" ? issue.keys[0] : undefined;
    fail("board_config_invalid_field", ["config", ...issue.path, ...(key ? [key] : [])].join("."));
  }
  const catalog = getDefaultRoleCatalog();
  const roles: Record<string, unknown> = {};
  for (const entry of config.roleSetups.filter((entry) => entry.count > 0)) {
    const contribution = catalog.requireRuntime(entry.role).configuration;
    if (contribution) roles[entry.role] = contribution.serialize(config);
  }
  const conditions = config.winConditions?.length
    ? config.winConditions
    : [config.winCondition ?? WinCondition.SlaughterCity];
  return parseBoardDefinition({
    version: 2,
    id,
    ruleset: RULESET,
    board: {
      size: config.boardSize,
      roleSetups: config.roleSetups.filter((entry) => entry.count > 0),
    },
    rules: { winConditions: conditions, hooks: config.hooks },
    mechanisms: {
      ...(config.events ? { eventPack: config.events.pack } : {}),
      disclosure: { deathRevealPolicy: config.disclosure?.deathRevealPolicy ?? "awa_hidden_v1" },
      lastWords: { policy: config.lastWords?.policy ?? "awa_initial_wave_v1" },
      sheriff: {
        enabled: config.enableSheriff,
        ...(config.enableSheriff
          ? {
              ...(config.initialSheriffSeat !== undefined
                ? { initialSeat: config.initialSheriffSeat }
                : {}),
              voteWeight: config.sheriff?.voteWeight ?? 1.5,
              electionPolicy: config.sheriff?.electionPolicy ?? "awa_final_candidates_v1",
              badgePolicy: config.sheriff?.badgePolicy ?? "awa_next_seat_v1",
              tieBreaker: config.tieBreaker?.sheriffVote ?? "min_seat",
            }
          : {}),
      },
      voting: { exilePolicy: config.voting?.exilePolicy ?? "awa_direct_v1" },
      selfDestruct: {
        enabledWindows: (config.selfDestruct?.enabledWindows ?? [ActionWindow.OnPreVote]).filter(
          (window) =>
            ({
              [ActionWindow.OnPreVote]: config.hooks.onPreVote,
              [ActionWindow.OnDaybreak]: config.hooks.onDaybreak,
              [ActionWindow.OnPreElection]: config.hooks.onPreElection,
              [ActionWindow.OnPerSpeechGap]: config.hooks.onPerSpeechGap,
            })[window],
        ),
      },
      tieBreaker: {
        exileVote: config.tieBreaker?.exileVote ?? "min_id",
        wolfKillVote: config.tieBreaker?.wolfKillVote ?? "min_id",
      },
    },
    roles,
  }).definition;
}

/**
 * 显式将旧板子覆盖转换为版本化 BoardDefinition，输出定义及有序迁移警告；正常加载不调用旧格式回退。
 * 已带版本的输入直接交给当前解析器；旧输入先按指定历史基板解析，再保存其实际生效参数。
 * 本模块只生成转换数据，不读写文件、运行对局或改归档指纹；默认值、裁掉的窗口及无效角色参数通过稳定警告码说明。
 */
import {
  boardDefinitionFromConfig,
  parseBoardDefinition,
  type BoardDefinition,
} from "./board_definition";
import { ActionWindow } from "../../core/domain/model";
import {
  parseBoardOverride,
  resolveBoardConfig,
  type BoardName,
} from "../scenarios/board_config_resolver";

export const MIGRATION_WARNING_CODES = [
  "legacy_defaults_resolved_explicitly",
  "legacy_single_win_condition_shadowed_by_effective_win_conditions",
  "legacy_empty_windows_used_default_pre_vote_window",
  "legacy_windows_with_disabled_hooks_removed_explicitly",
  "legacy_unused_witch_parameters_removed_explicitly",
  "legacy_unsupported_windows_removed_explicitly",
] as const;
export type MigrationWarningCode = (typeof MIGRATION_WARNING_CODES)[number];
/** warnings 描述显式归一产生的差异；它们是迁移说明，不能当作运行时规则或通用容错授权。 */
export interface BoardMigration {
  definition: BoardDefinition;
  warnings: MigrationWarningCode[];
}

export function convertLegacyBoard(
  raw: unknown,
  boardId: string,
  legacyBase?: BoardName,
): BoardMigration {
  if (raw && typeof raw === "object" && "version" in raw) {
    return { definition: parseBoardDefinition(raw, boardId).definition, warnings: [] };
  }
  const base = legacyBase ?? boardId;
  if (base !== "six_player_mvp" && base !== "twelve_player_standard") {
    throw new Error("board_config_legacy_base_unknown");
  }
  const override = parseBoardOverride(raw, (legacyBase ?? boardId) as BoardName);
  if (!override) throw new Error("board_config_legacy_shape_invalid");
  const historical = { ...override };
  // 空自爆窗口在旧执行中触发默认窗口；先按旧语义展开，再转换，不能把空数组解释为新禁用政策。
  if (historical.selfDestruct?.enabledWindows.length === 0) delete historical.selfDestruct;
  const effective = resolveBoardConfig(base as BoardName, historical);
  // 当前版本只保留既有可执行的 OnPreVote 窗口；移除其它旧项时明确报警，不静默改变旧档来源。
  const unsupported =
    effective.selfDestruct?.enabledWindows.filter((window) => window !== ActionWindow.OnPreVote) ??
    [];
  if (unsupported.length)
    effective.selfDestruct = {
      enabledWindows: effective.selfDestruct!.enabledWindows.filter(
        (window) => window === ActionWindow.OnPreVote,
      ),
    };
  const warnings: MigrationWarningCode[] = ["legacy_defaults_resolved_explicitly"];
  if (unsupported.length) warnings.push("legacy_unsupported_windows_removed_explicitly");
  // 警告顺序固定，单一旧判胜项被实际生效的列表覆盖时也保留解释，定义只序列化最终配置。
  if (override.winCondition && effective.winConditions?.length)
    warnings.push("legacy_single_win_condition_shadowed_by_effective_win_conditions");
  if (override.selfDestruct?.enabledWindows.length === 0 && effective.hooks.onPreVote)
    warnings.push("legacy_empty_windows_used_default_pre_vote_window");
  const windowHooks = {
    [ActionWindow.OnPreVote]: effective.hooks.onPreVote,
    [ActionWindow.OnDaybreak]: effective.hooks.onDaybreak,
    [ActionWindow.OnPreElection]: effective.hooks.onPreElection,
    [ActionWindow.OnPerSpeechGap]: effective.hooks.onPerSpeechGap,
  };
  if (
    [...unsupported, ...(effective.selfDestruct?.enabledWindows ?? [])].some(
      (window) => !windowHooks[window],
    )
  )
    warnings.push("legacy_windows_with_disabled_hooks_removed_explicitly");
  if (
    override.witch &&
    !effective.roleSetups.some((entry) => entry.role === "witch" && entry.count > 0)
  )
    warnings.push("legacy_unused_witch_parameters_removed_explicitly");
  return { definition: boardDefinitionFromConfig(boardId, effective), warnings };
}
